import{_ as e,c as t,o as a,a4 as s}from"./chunks/framework.ttppV29E.js";const o="/assets/http-requestv2.BffaaiAl.png",i="/assets/http-request-headersv2.C-v7GsTD.png",r="/assets/http-request-certsv2.9o3n5Boi.png",b=JSON.parse('{"title":"HTTP Request Task","description":"","frontmatter":{},"headers":[],"relativePath":"docs/endpoints/http-request.md","filePath":"docs/endpoints/http-request.md","lastUpdated":1791474926000}'),n={name:"docs/endpoints/http-request.md"},d=s('<h1 id="http-request-task" tabindex="-1">HTTP Request Task <a class="header-anchor" href="#http-request-task" aria-label="Permalink to &quot;HTTP Request Task&quot;">​</a></h1><p>The HTTP Request task is used to communicate with external services. You can use this to send data to your APIs, or fetch data from other sources.</p><p><img src="'+o+'" alt="RequestTask"></p><h3 id="creating-a-request" tabindex="-1">Creating a Request <a class="header-anchor" href="#creating-a-request" aria-label="Permalink to &quot;Creating a Request&quot;">​</a></h3><p>The <code>URL</code> field is the request address, with the HTTP method defined to its right. The following HTTP Verbs are accepted: <code>POST</code>, <code>GET</code>, <code>PATCH</code>, <code>PUT</code>, <code>DELETE</code>, <code>HEAD</code>, <code>OPTIONS</code>, and <code>TRACE</code>. The payload can be provided by URL query string, or by body content.</p><h3 id="retry-requests-on-failure" tabindex="-1">Retry requests on failure <a class="header-anchor" href="#retry-requests-on-failure" aria-label="Permalink to &quot;Retry requests on failure&quot;">​</a></h3><p>If selected, AireGlu will automatically retry the request if it fails due to temporary issues like network problems or server unavailability:</p><ul><li>HTTP 500 and above (Server errors)</li><li>HTTP 408 (Request timeout)</li><li>HttpRequestException</li><li>TimeoutRejectedException</li></ul><p>AireGlu will not retry the request for errors like authentication failures or invalid input.</p><p>The request will be retried twice (in addition to the initial request) with a starting delay of 2 seconds and an exponential back-off.</p><h3 id="retain-status-code" tabindex="-1">Retain status code <a class="header-anchor" href="#retain-status-code" aria-label="Permalink to &quot;Retain status code&quot;">​</a></h3><p>If selected, the endpoint returns this request&#39;s response status code as its own. Use this when your endpoint fronts another service and the caller needs that service&#39;s status code (e.g. a <code>404</code> or <code>500</code>) rather than a <code>200</code>.</p><ul><li><strong>With an <a href="./http-response.html">HTTP Response</a> task:</strong> the HTTP Response task&#39;s body and headers are returned, with this request&#39;s status code.</li><li><strong>Without an HTTP Response task:</strong> despite the name, this request&#39;s response <strong>body</strong> is returned too, along with its status code, replacing the <a href="./http-response.html#omitting-this-task">results of every task</a>. Other tasks still run, but their results aren&#39;t returned. Response headers are not passed on.</li><li>If more than one task has this enabled, the last one in the endpoint is used.</li><li>This still applies if the task is skipped by a <a href="./tasks.html#filters">filter</a>. A skipped task&#39;s status code is <code>200</code>.</li><li>An <a href="./http-redirect.html">HTTP Redirect</a> task takes precedence over this setting.</li></ul><p>If <a href="/docs/getting-started/endpoints.html"><code>Stop on Task Failure</code></a> is enabled (the default), a failing task&#39;s status code is already returned, so this setting mainly matters for non-<code>200</code> success codes (e.g. <code>201</code>), when Stop on Task Failure is off, or alongside an HTTP Response task. See <a href="/docs/getting-started/endpoints.html#how-the-endpoint-response-is-decided">How the endpoint response is decided</a>.</p><p>This option is also available on the <a href="./sms.html">SMS</a> task.</p><h3 id="authorisation" tabindex="-1">Authorisation <a class="header-anchor" href="#authorisation" aria-label="Permalink to &quot;Authorisation&quot;">​</a></h3><p>The HTTP Request task supports an authentication via the <code>Auth Type</code> field under the Authorisation tab. The following options are available:</p><ul><li><strong>None</strong>: No authentication will be used.</li><li><strong>Client Connection</strong>: Select a pre-configured Client Connection to automatically obtain and use an access token for authentication. Read more about Connections in the <a href="./../connections/connections.html">Connections documentation</a>.</li></ul><h3 id="headers" tabindex="-1">Headers <a class="header-anchor" href="#headers" aria-label="Permalink to &quot;Headers&quot;">​</a></h3><p>Some headers will be automatically added, such as content-type, which will correspond to the select format of your request.</p><p>Some requests may require additional headers to work correctly. E.g. for authentication. By expanding the Headers section, you can add headers to the request. The <code>Header</code> field contains the Key, and one or more values can be added.</p><p><img src="'+i+'" alt="RequestTask"></p><h3 id="response-headers" tabindex="-1">Response headers <a class="header-anchor" href="#response-headers" aria-label="Permalink to &quot;Response headers&quot;">​</a></h3><p>The headers returned by the service can be used in later tasks via Liquid, e.g. <span><code>{{ endpoint.tasks[0].headers[&quot;X-Request-Id&quot;] | first }}</code></span>. Only map the headers you need, as they can contain sensitive values. See <a href="/docs/quickstart/liquid.html#http-request-task-response-headers">HTTP Request task response headers</a>.</p><h3 id="certificates" tabindex="-1">Certificates <a class="header-anchor" href="#certificates" aria-label="Permalink to &quot;Certificates&quot;">​</a></h3><p>Certificates are used for client authentication via Mutual TLS. For the most part, this is not required, but some services may need this. The client certificate should be bundled with the private key in a PKCS#12 ( or .pfx) format, and it should be password protected.</p><p>Certificates can be stored in two ways:</p><ol><li>Within the endpoint definition itself (certificate type - <code>File</code>)</li><li>Stored as an AireGlu <a href="./../getting-started/secrets.html">Secret</a> and referenced in the <code>Secret</code> field</li></ol><p><img src="'+r+'" alt="RequestTask"></p><h3 id="stream-input" tabindex="-1">Stream Input <a class="header-anchor" href="#stream-input" aria-label="Permalink to &quot;Stream Input&quot;">​</a></h3><p>If your endpoint&#39;s <a href="/docs/endpoint-input/input.html">input</a> format is set to <code>Stream</code>, you can forward that raw input straight through as the request body, without it being decoded or re-encoded.</p><p>Set the request body&#39;s <code>Format</code> to <code>Stream</code>. The body editor defaults to the template:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{input.stream}}</span></span></code></pre></div><p>This is a literal passthrough token, not a Liquid expression to be evaluated. When the body consists of only this token (or the equivalent <code>--*stream*--</code> token), AireGlu sends the endpoint&#39;s raw input stream straight through byte-for-byte, skipping the usual mapping/transform step entirely.</p><p>A few things to note:</p><ul><li>This only forwards the endpoint&#39;s own input - it can&#39;t be used to forward a stream produced by an earlier task (e.g. an <a href="./http-response-handler.html">HTTP Response Handler</a>&#39;s stream output).</li><li>It only works when the token is the entire body. Anything else in the template means the stream is not passed through raw.</li><li>No <code>content-type</code> header is added automatically for a Stream body - add one yourself under Headers if the destination needs it.</li></ul><h3 id="stream-response" tabindex="-1">Stream Response <a class="header-anchor" href="#stream-response" aria-label="Permalink to &quot;Stream Response&quot;">​</a></h3><p>It is now possible to receive binary streams from an HTTP Request task, such as when requesting content with media types like <code>image/jpeg</code> or <code>application/pdf</code>.</p><h4 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h4><ul><li>Streams from an HTTP Request task cannot currently be mapped into another task.</li><li>To return a binary stream from your endpoint, the HTTP Request task must be the final output of the endpoint&#39;s execution pipeline.</li></ul>',40),h=[d];function l(c,u,p,m,f,q){return a(),t("div",null,h)}const k=e(n,[["render",l]]);export{b as __pageData,k as default};
